-- MedicApp on Postgres (Supabase).
--
-- The same tables the SQLite engine builds (server/db-sqlite.js), in their
-- current shape. Two deliberate choices keep one set of SQL working on both:
--   * Timestamps are ISO-8601 text. COLLATE "C" makes them sort and compare by
--     plain character order, which for that format is chronological order.
--   * Yes/no columns are integers (0 or 1).
--
-- Nothing here is reachable through Supabase's auto-generated API: row level
-- security is on with no policies, and the public roles have no privileges.
-- Only the `api` Edge Function, which connects as the database owner, reads
-- or writes these tables.

create table users (
  id            integer generated by default as identity primary key,
  username      text not null,
  name          text not null,
  role          text not null check (role in ('admin', 'staff')),
  job_title     text not null default '',
  password_hash text not null,
  active        integer not null default 1,
  created_at    text collate "C" not null,
  removed_at    text collate "C"
);
-- Removed accounts keep their rows (the audit trail points at them), so a
-- username only has to be unique among accounts that can still sign in.
create unique index users_username_active on users (username) where active = 1;

create table sessions (
  token_hash text primary key,
  user_id    integer not null references users (id),
  created_at text collate "C" not null,
  expires_at text collate "C" not null
);
create index sessions_user on sessions (user_id);

create table facility (
  id         integer primary key check (id = 1),
  name       text not null,
  address    text not null default '',
  latitude   double precision not null,
  longitude  double precision not null,
  radius_m   integer not null default 100,
  timezone   text not null default 'UTC',
  updated_at text collate "C" not null
);

create table clock_events (
  id         integer generated by default as identity primary key,
  user_id    integer not null references users (id),
  type       text not null check (type in ('in', 'out')),
  status     text not null check (status in ('ok', 'blocked')),
  "at"       text collate "C" not null,
  latitude   double precision,
  longitude  double precision,
  accuracy_m double precision,
  distance_m double precision,
  radius_m   integer,
  on_site    integer,
  forced_by  integer references users (id),
  note       text not null default ''
);
create index clock_events_user_at on clock_events (user_id, "at");
create index clock_events_at on clock_events ("at");
create index clock_events_forced_by on clock_events (forced_by);

create table patients (
  id          integer generated by default as identity primary key,
  name        text not null,
  room        text not null,
  notes       text not null default '',
  active      integer not null default 1,
  created_at  text collate "C" not null,
  archived_at text collate "C"
);

create table medications (
  id            integer generated by default as identity primary key,
  patient_id    integer not null references patients (id),
  name          text not null,
  dosage        text not null,
  instructions  text not null default '',
  times         text not null,
  active        integer not null default 1,
  created_at    text collate "C" not null,
  ended_at      text collate "C",
  prn           integer not null default 0,
  prn_min_hours double precision,
  prn_max_daily integer
);
create index medications_patient on medications (patient_id);

create table administrations (
  id             integer generated by default as identity primary key,
  medication_id  integer not null references medications (id),
  patient_id     integer not null references patients (id),
  scheduled_date text not null,
  scheduled_time text,
  med_name       text not null,
  dosage         text not null,
  outcome        text not null default 'given' check (outcome in ('given', 'refused', 'held')),
  recorded_by    integer not null references users (id),
  recorded_at    text collate "C" not null,
  note           text not null default '',
  voided_at      text collate "C",
  voided_by      integer references users (id),
  void_reason    text
);
-- One live record per scheduled dose. Voided records and as-needed doses
-- (no scheduled time) are not counted.
create unique index administrations_slot on administrations (medication_id, scheduled_date, scheduled_time)
  where voided_at is null and scheduled_time is not null;
create index administrations_date on administrations (scheduled_date);
create index administrations_medication on administrations (medication_id, recorded_at);
create index administrations_patient on administrations (patient_id);
create index administrations_recorded_by on administrations (recorded_by);
create index administrations_voided_by on administrations (voided_by);

create table messages (
  id           integer generated by default as identity primary key,
  sender_id    integer not null references users (id),
  recipient_id integer references users (id),
  subject      text not null,
  body         text not null,
  priority     text not null default 'normal' check (priority in ('normal', 'important')),
  created_at   text collate "C" not null
);
create index messages_sender on messages (sender_id);
create index messages_recipient on messages (recipient_id);

create table message_reads (
  message_id      integer not null references messages (id),
  user_id         integer not null references users (id),
  read_at         text collate "C" not null,
  acknowledged_at text collate "C",
  primary key (message_id, user_id)
);
create index message_reads_user on message_reads (user_id);

create table message_replies (
  id         integer generated by default as identity primary key,
  message_id integer not null references messages (id),
  staff_id   integer not null references users (id),
  author_id  integer not null references users (id),
  body       text not null,
  created_at text collate "C" not null,
  read_at    text collate "C"
);
create index message_replies_thread on message_replies (message_id, staff_id);
create index message_replies_staff on message_replies (staff_id);
create index message_replies_author on message_replies (author_id);

create table app_settings (
  key   text primary key,
  value text not null
);

create table login_attempts (
  key      text primary key,
  first_at text collate "C" not null,
  attempts integer not null
);

-- Lock every table away from Supabase's public API.
do $$
declare t text;
begin
  foreach t in array array['users', 'sessions', 'facility', 'clock_events', 'patients', 'medications', 'administrations',
                           'messages', 'message_reads', 'message_replies', 'app_settings', 'login_attempts']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
  end loop;
end $$;
